CREATE OR REPLACE FUNCTION public.sync_account_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.email is null then
    delete from public.account_emails where user_id = new.id;
    return new;
  end if;

  insert into public.account_emails (user_id, email)
  values (new.id, lower(trim(new.email)))
  on conflict (user_id) do update
    set email = excluded.email, updated_at = now();

  return new;
end;
$function$;

grant execute on function public.sync_account_email() to anon;
grant execute on function public.sync_account_email() to authenticated;
grant execute on function public.sync_account_email() to public;
grant execute on function public.sync_account_email() to service_role;
